cat > frontend.go <<'EOF'
package main

import (
    "encoding/json"
    "fmt"
    "io"
    "net/url"
    "strings"
)

func wordSet(s string) map[string]bool {
    m := make(map[string]bool)
    for _, v := range strings.Fields(s) { m[v] = true }
    return m
}

type Frontend struct {
    Args []string
    DryRun, PrettyOut, PrettyErr, Verbose, Silent, Help bool
    Preview []byte
    InputTTY bool
}

// splitOptions preserves both the order of flags and the order of operands.
// It expands short-option clusters, but does not split a flag's argument.
func splitOptions(args []string) (flags, operands []string) {
    end := false
    for i := 0; i < len(args); i++ {
        a := args[i]
        if end || len(a) < 2 || a[0] != '-' {
            operands = append(operands, a)
            continue
        }
        if a == "--" { end = true; continue }
        if strings.HasPrefix(a, "--") {
            flags = append(flags, a)
            if frontendParameters[a] && i+1 < len(args) {
                i++; flags = append(flags, args[i])
            }
            continue
        }
        for j := 1; j < len(a); j++ {
            flag := "-" + string(a[j])
            flags = append(flags, flag)
            if frontendParameters[flag] {
                if j+1 < len(a) { flags = append(flags, a[j+1:])
                } else if i+1 < len(args) { i++; flags = append(flags, args[i]) }
                break
            }
        }
    }
    return
}

func normalizeURL(s string, out, errout io.Writer) string {
    explicit := strings.HasPrefix(s, "http://") || strings.HasPrefix(s, "https://")
    if !explicit { s = "http://" + strings.TrimPrefix(s, "//") }
    fmt.Fprintln(errout, s)
    u, err := url.Parse(s)
    if err != nil { fmt.Fprint(out, err); return s }
    if u.Host != "" && u.Hostname() == "" {
        u.Host = "localhost"
        if p := strings.TrimPrefix(s, u.Scheme+"://"); strings.HasPrefix(p, ":") {
