#include "curl_bridge.h"

extern size_t onCurlWrite(char *, size_t);
extern size_t onCurlHeader(char *, size_t);
extern size_t onCurlRead(char *, size_t);
extern int onCurlDebug(int, char *, size_t);

static size_t write_cb(char *p, size_t s, size_t n, void *u) {
    (void)u; return onCurlWrite(p, s*n);
}
static size_t header_cb(char *p, size_t s, size_t n, void *u) {
    (void)u; return onCurlHeader(p, s*n);
}
static size_t read_cb(char *p, size_t s, size_t n, void *u) {
    (void)u; return onCurlRead(p, s*n);
}
static int debug_cb(CURL *c, curl_infotype t, char *p, size_t n, void *u) {
    (void)c; (void)u; return onCurlDebug((int)t,p,n);
}
void *bridge_init(void) {
    CURL *c = curl_easy_init();
    if (!c) return NULL;
    curl_easy_setopt(c, CURLOPT_WRITEFUNCTION, write_cb);
