func (t *transfer) previewOut(){
    if t.previewWritten||!t.conf.front.Verbose||!t.conf.verbose{return}
    t.previewWritten=true
    p:=&JSONPrinter{Writer:t.stderr,Pretty:t.conf.front.PrettyErr&&!t.rawStderr}
    p.Write(t.preview);io.WriteString(t.stderr,"\n\n")
