//export onCurlWrite
func onCurlWrite(p *C.char,n C.size_t) C.size_t{
    t:=active;if t==nil{return n}
    b:=C.GoBytes(unsafe.Pointer(p),C.int(n))
    if t.outputName!=""&&t.outputFile==nil{
        if t.conf.createDirs{os.MkdirAll(filepath.Dir(t.outputName),0755)}
        f,e:=os.Create(t.outputName);if e!=nil{return 0};t.outputFile=f;t.output=f
