}

//export onCurlHeader
func onCurlHeader(p *C.char,n C.size_t) C.size_t{
    t:=active;if t==nil{return n};b:=C.GoBytes(unsafe.Pointer(p),C.int(n));s:=string(b)
    if strings.HasPrefix(s,"HTTP/"){t.headers=nil}
    t.headers=append(t.headers,s)
    if t.dump!=nil{t.dump.Write(b)}
    if t.conf.remoteName&&t.conf.remoteHeaderName&&strings.HasPrefix(strings.ToLower(s),"content-disposition:"){
        low:=strings.ToLower(s);if i:=strings.Index(low,"filename=");i>=0{name:=strings.TrimSpace(s[i+9:]);name=strings.Trim(name,"\";\r\n");if name!=""{t.outputName=filepath.Base(name)}}
    }
