}

//export onCurlRead
func onCurlRead(p *C.char,n C.size_t) C.size_t{
    t:=active;if t==nil{return 0};count:=int(n);if count>len(t.body)-t.readPos{count=len(t.body)-t.readPos}
    if count>0{C.memcpy(unsafe.Pointer(p),unsafe.Pointer(&t.body[t.readPos]),C.size_t(count));t.readPos+=count}
    return C.size_t(count)
}

//export onCurlDebug
func onCurlDebug(kind C.int,p *C.char,n C.size_t) C.int{
    t:=active;if t==nil{return 0};b:=C.GoBytes(unsafe.Pointer(p),C.int(n));s:=string(b)
    full:=t.conf.front.Verbose;pretty:=t.conf.front.PrettyErr&&!t.rawStderr
    switch int(kind){
    case int(C.CURLINFO_TEXT):
        if full {
            if strings.HasPrefix(s,"Closing connection")||strings.Contains(s,"left intact"){t.previewOut()}
            for _,line:=range strings.SplitAfter(s,"\n"){if line!=""{writeLines(t.stderr,"* "+line,pretty)}}
