        if t.rawStderr {writeLines(t.stderr,"< "+s,false)}else{writeLines(t.stderr,s,pretty)}
    case int(C.CURLINFO_HEADER_OUT):
        if full{
            if t.rawStderr {for _,line:=range strings.SplitAfter(s,"\n"){if line!=""{writeLines(t.stderr,"> "+line,false)}}}else{writeLines(t.stderr,s,pretty)}
