        }
    case int(C.CURLINFO_DATA_IN): if full{t.previewOut()}
    case int(C.CURLINFO_DATA_OUT): if full && len(t.preview)==0 && len(t.body)>0{t.previewOut()}
    }
    return 0
}

func (t *transfer) writeResult(code int){
    format:=t.conf.writeOut
    writer:=io.Writer(t.stdout)
    for len(format)>0{
        if strings.HasPrefix(format,"%{"){
            end:=strings.IndexByte(format,'}');if end<0{io.WriteString(writer,format);break}
            key:=format[2:end];format=format[end+1:]
            if key=="stderr"{writer=t.stderr;continue};if key=="stdout"{writer=t.stdout;continue};if key=="onerror"{if code==0{return};continue}
