        }else if len(format)>1&&format[0]=='\\'{switch format[1]{case 'n':io.WriteString(writer,"\n");case 'r':io.WriteString(writer,"\r");case 't':io.WriteString(writer,"\t");default:io.WriteString(writer,format[:2])};format=format[2:]
        }else{io.WriteString(writer,format[:1]);format=format[1:]}
    }
}

func (t *transfer) resultVariable(name string,code int)(string,bool){
    switch name{
    case "http_code","response_code":return fmt.Sprintf("%03d",t.infoLong(C.CURLINFO_RESPONSE_CODE)),true
    case "exitcode":return strconv.Itoa(code),true
    case "errormsg":return t.errorString,true
    case "url_effective":return t.infoString(C.CURLINFO_EFFECTIVE_URL),true
    case "content_type":return t.infoString(C.CURLINFO_CONTENT_TYPE),true
    case "redirect_url":return t.infoString(C.CURLINFO_REDIRECT_URL),true
    case "remote_ip":return t.infoString(C.CURLINFO_PRIMARY_IP),true
    case "local_ip":return t.infoString(C.CURLINFO_LOCAL_IP),true
    case "filename_effective":return t.outputName,true
    case "scheme":return t.infoString(C.CURLINFO_SCHEME),true
    case "method":return t.infoString(C.CURLINFO_EFFECTIVE_METHOD),true
    case "http_version":
        v:=t.infoLong(C.CURLINFO_HTTP_VERSION);return map[int64]string{0:"0",1:"1.0",2:"1.1",3:"2",30:"3"}[v],true
    }
    longs:=map[string]C.int{"num_redirects":C.CURLINFO_REDIRECT_COUNT,"remote_port":C.CURLINFO_PRIMARY_PORT,"local_port":C.CURLINFO_LOCAL_PORT,"size_header":C.CURLINFO_HEADER_SIZE,"size_request":C.CURLINFO_REQUEST_SIZE,"num_connects":C.CURLINFO_NUM_CONNECTS,"ssl_verify_result":C.CURLINFO_SSL_VERIFYRESULT,"http_connect":C.CURLINFO_HTTP_CONNECTCODE,"proxy_ssl_verify_result":C.CURLINFO_PROXY_SSL_VERIFYRESULT}
    if opt,ok:=longs[name];ok{return strconv.FormatInt(t.infoLong(opt),10),true}
    doubles:=map[string]C.int{"time_total":C.CURLINFO_TOTAL_TIME,"time_namelookup":C.CURLINFO_NAMELOOKUP_TIME,"time_connect":C.CURLINFO_CONNECT_TIME,"time_appconnect":C.CURLINFO_APPCONNECT_TIME,"time_pretransfer":C.CURLINFO_PRETRANSFER_TIME,"time_starttransfer":C.CURLINFO_STARTTRANSFER_TIME,"time_redirect":C.CURLINFO_REDIRECT_TIME,"size_download":C.CURLINFO_SIZE_DOWNLOAD,"size_upload":C.CURLINFO_SIZE_UPLOAD,"speed_download":C.CURLINFO_SPEED_DOWNLOAD,"speed_upload":C.CURLINFO_SPEED_UPLOAD}
    if opt,ok:=doubles[name];ok{v:=t.infoDouble(opt);if strings.HasPrefix(name,"time_"){return fmt.Sprintf("%.6f",v),true};return fmt.Sprintf("%.0f",v),true}
    return "",false
}
