func terminal(fd int) bool { return C.isatty(C.int(fd)) != 0 }

type dataPart struct { kind, value string }
type nativeValue struct { name, s string; n int64; text bool }
type requestConfig struct {
    front *Frontend
    urls, headers, proxyHeaders, resolve, connectTo, cookies []string
    data, forms []dataPart
    native []nativeValue
    method, upload, user, proxyUser string
    uploadSet, head, include, get, verbose, fail, failBody, globoff bool
    outputs []string
