    remoteName, remoteHeaderName, createDirs bool
    retry int
    retryDelay, retryMax float64
    retryConnRefused, retryAll, failEarly bool
    stdin []byte
    stdinRead bool
    traceFile string
    traceASCII, traceTime bool
    requestType string
}

func (c *requestConfig) num(name string, value int64) { c.native = append(c.native,nativeValue{name:name,n:value}) }
func (c *requestConfig) str(name, value string) { c.native = append(c.native,nativeValue{name:name,s:value,text:true}) }

func optionError(f *Frontend, arg, message string) int {
    writeLines(os.Stderr, "curl: option "+arg+": "+message+"\ncurl: try 'curl --help' or 'curl --manual' for more information\n", f.PrettyErr)
    return 2
}

func canonicalOption(a string) (optionSpec, string) {
    for _, s := range optionSpecs { if s.Short != "" && a == s.Short || a == s.Long { return s, "" } }
    if strings.HasPrefix(a,"--") && !strings.Contains(a,"=") {
        name:=a
        negative:=false
        if strings.HasPrefix(name,"--no-") { negative=true;name="--"+strings.TrimPrefix(name,"--no-") }
        var matches []optionSpec
        for _, s := range optionSpecs {
            if strings.HasPrefix(s.Long,name) { matches=append(matches,s) }
        }
        if len(matches)==1 {
            if negative && matches[0].Parameter { return optionSpec{},"is unknown" }
            return matches[0], ""
        }
        if len(matches)>1 { return optionSpec{},"is ambiguous" }
    }
    return optionSpec{},"is unknown"
}

func (c *requestConfig) readInput() []byte {
    if !c.stdinRead { c.stdin,_=io.ReadAll(os.Stdin);c.stdinRead=true }
    return c.stdin
}

func run(f *Frontend) int {
    c, code, done := parseCurl(f)
    if done { return code }
    if len(c.urls)==0 {
        writeLines(os.Stderr,"curl: no URL specified!\ncurl: try 'curl --help' or 'curl --manual' for more information\n",f.PrettyErr)
        return 2
    }
