    c.num("NOSIGNAL",1);c.num("NOPROGRESS",1);c.num("TCP_KEEPALIVE",1);c.num("TCP_KEEPIDLE",60);c.num("TCP_KEEPINTVL",60)
    c.num("TCP_NODELAY",1)
    c.str("USERAGENT","curl/7.81.0")
    for i:=0; i<len(args); i++ {
        a:=args[i]
