package main

import (
    "fmt"
    "net"
    "regexp"
    "strconv"
    "strings"
)

var numericRange = regexp.MustCompile(`^([0-9]+)-([0-9]+)(?::([0-9]+))?$`)
var alphaRange = regexp.MustCompile(`^([a-zA-Z])-([a-zA-Z])(?::([0-9]+))?$`)

func expandGlobs(address string) ([]string,string) {
    errorAt:=func(reason string,position int)([]string,string){
        return nil,fmt.Sprintf("%s in URL position %d:\n%s\n%s^\n",reason,position,address,strings.Repeat(" ",position-1))
    }
    results:=[]string{""}
    appendText:=func(s string){for i:=range results{results[i]+=s}}
    for i:=0;i<len(address);i++ {
        ch:=address[i]
        if ch=='\\'&&i+1<len(address){i++;appendText(address[i:i+1]);continue}
        if ch=='}'||ch==']'{return errorAt("unmatched close brace/bracket",i+1)}
        if ch!='{'&&ch!='['{appendText(address[i:i+1]);continue}
        close:=byte('}');if ch=='['{close=']'}
        j:=strings.IndexByte(address[i+1:],close)
        if j>=0{j+=i+1}
        var choices []string
        if ch=='{'{
            if j<0{return errorAt("unmatched brace",i+1)}
            content:=address[i+1:j]
            if k:=strings.IndexByte(content,'{');k>=0{return errorAt("nested brace",i+k+2)}
            choices=strings.Split(content,",")
        }else{
            if j<0{return errorAt("bad range",len(address)+1)}
            content:=address[i+1:j]
            ipContent:=strings.SplitN(content,"%",2)[0]
            if content==""||net.ParseIP(ipContent)!=nil {appendText(address[i:j+1]);i=j;continue}
            if r:=numericRange.FindStringSubmatch(content);r!=nil{
                lo,e1:=strconv.ParseInt(r[1],10,64);hi,e2:=strconv.ParseInt(r[2],10,64);step:=int64(1)
                if r[3]!=""{step,_=strconv.ParseInt(r[3],10,64)}
                if e1!=nil||e2!=nil||step<=0||lo>hi||hi-lo>1000000{return errorAt("bad range",j+2)}
                width:=0;if r[1][0]=='0'{width=len(r[1])}
                for n:=lo;n<=hi;n+=step{choices=append(choices,fmt.Sprintf("%0*d",width,n))}
            }else if r:=alphaRange.FindStringSubmatch(content);r!=nil{
                lo,hi:=int(r[1][0]),int(r[2][0]);step:=1;if r[3]!=""{step,_=strconv.Atoi(r[3])}
                if step<=0||lo>hi{return errorAt("bad range",i+2)}
                for n:=lo;n<=hi;n+=step{choices=append(choices,string(rune(n)))}
            }else{return errorAt("bad range",i+2)}
        }
        var next []string
        for _,prefix:=range results{for _,value:=range choices{next=append(next,prefix+value)}}
        results=next;i=j
    }
    return results,""
}
EOF
