package main

import "io"

// pipeWriter models the transport's stdout buffering. Formatting is applied
// after the transport buffer, just as for bytes received through a pipe.
type pipeWriter struct {
    destination io.Writer
    immediate bool
    pending []byte
}

func (w *pipeWriter) Write(p []byte) (int,error) {
    if w.immediate {return w.destination.Write(p)}
    w.pending=append(w.pending,p...)
    if len(w.pending)>=4096 {if err:=w.Flush();err!=nil{return 0,err}}
    return len(p),nil
}
func (w *pipeWriter) Flush() error {
    if len(w.pending)==0{return nil}
    _,err:=w.destination.Write(w.pending)
    w.pending=w.pending[:0]
    return err
}
