package main

import (
    "bytes"
    "strings"
    "testing"
)

func TestStreamingJSON(t *testing.T){
    raw:=[]byte(`{"a":1,"b":[true,"x"],"z":null}`)
    want:=white+"{\n    "+blue+`"a"`+white+": "+cyan+"1"+white+",\n    "+blue+`"b"`+white+": "+white+"[\n        true"+white+",\n        "+blue+`"x"`+"\n    "+white+"]"+white+",\n    "+blue+`"z"`+white+": "+magenta+"null\n"+white+"}\n"+reset
    for chunk:=1;chunk<=len(raw);chunk++{
        var out bytes.Buffer
        p:=JSONPrinter{Writer:&out,Pretty:true}
        for at:=0;at<len(raw);at+=chunk{end:=at+chunk;if end>len(raw){end=len(raw)};p.Write(raw[at:end])}
        if out.String()!=want{t.Fatalf("chunk %d:\n%q\nwant %q",chunk,out.String(),want)}
    }
}

func TestFormattingModes(t *testing.T){
    tests:=[]struct{in,want string}{
        {"{}",white+"{\n    \n"+white+"}\n"+reset},
        {"[]",white+"[\n    \n"+white+"]\n"+reset},
        {" {}\n"," {}\n"},
        {"hello\nworld\n","hello\nworld\n"},
        {`{"x":what`,white+"{\n    "+blue+`"x"`+white+": "+cyan+"what"},
        {"{}\n{}\n",strings.Repeat(white+"{\n    \n"+white+"}\n"+reset,2)},
    }
    for _,tc:=range tests{
        var out bytes.Buffer;p:=JSONPrinter{Writer:&out,Pretty:true};p.Write([]byte(tc.in))
        if out.String()!=tc.want{t.Errorf("%q: got %q, want %q",tc.in,out.String(),tc.want)}
    }
}

func TestBinaryNotice(t *testing.T){
    var out bytes.Buffer
    p:=JSONPrinter{Writer:&out,Pretty:true}
    p.Write([]byte{'a',0,'z'});p.Write([]byte("more"))
    want:="+-----------------------------------------+\n| NOTE: binary data not shown in terminal |\n+-----------------------------------------+\n"
    if out.String()!=want{t.Fatal(out.String())}
}

func TestHTTPColors(t *testing.T){
    if got:=colorLine("HTTP/1.1 404 Not Found\r");got!=blue+"HTTP"+white+"/"+cyan+"1.1 404"+yellow+" Not Found\r"+reset{t.Fatal(got)}
    if got:=colorLine("X-Foo: x:y\r");got!=white+"X-Foo:"+cyan+" x:y\r"+reset{t.Fatal(got)}
    if got:=colorLine("\r");got!="\r"{t.Fatal(got)}
}

func TestTransportBuffer(t *testing.T){
    var out bytes.Buffer
    p:=pipeWriter{destination:&out}
    p.Write([]byte("abc"));if out.Len()!=0{t.Fatal("premature output")}
    p.Flush();if out.String()!="abc"{t.Fatal(out.String())}
    p.immediate=true;p.Write([]byte("x"));if out.String()!="abcx"{t.Fatal(out.String())}
}
