#!/usr/bin/env python3
"""Self-contained CLI checks; run ./compile.sh first."""
import http.server
import json
import os
from pathlib import Path
import subprocess
import tempfile
import threading

EXE = str(Path(__file__).resolve().parents[1] / "executable")


class Handler(http.server.BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *args):
        pass

    def do_GET(self):
        data = self.rfile.read(int(self.headers.get("Content-Length", "0")))
        self.server.last = (self.command, self.path, dict(self.headers), data)
        body = b'{"a":1,"ok":true}\n'
        code = 404 if self.path.startswith("/missing") else 200
        self.send_response_only(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Connection", "close")
        self.end_headers()
        self.wfile.write(body)

    do_POST = do_PUT = do_PATCH = do_DELETE = do_GET


def invoke(*args, input=b""):
    env = os.environ.copy()
    env["NO_PROXY"] = "127.0.0.1,localhost"
    return subprocess.run([EXE, *args], input=input, capture_output=True,
                          env=env, timeout=10)


def main():
    server = http.server.HTTPServer(("127.0.0.1", 0), Handler)
    worker = threading.Thread(target=server.serve_forever, daemon=True)
    worker.start()
    url = "http://127.0.0.1:%d" % server.server_port
    try:
        result = invoke("-q", url)
        assert result.returncode == 0, result.stderr
        assert result.stdout == b'{"a":1,"ok":true}\n'
        assert result.stderr == (url + "\n").encode()
        assert server.last[0] == "POST"
        assert server.last[2]["Content-Type"] == "application/json"

        result = invoke("-q", "PUT", url, "x=hello world", "n:=3", "q==a+b")
        assert result.returncode == 0, result.stderr
        assert server.last[0] == "PUT"
        assert server.last[1] == "/?q=a%2Bb"
        assert json.loads(server.last[3]) == {"n": 3, "x": "hello world"}

        result = invoke("-q", "--pretty", url)
        assert result.stdout == (b'\x1b[37m{\n    \x1b[34m"a"\x1b[37m: '
                                 b'\x1b[36m1\x1b[37m,\n    \x1b[34m"ok"'
                                 b'\x1b[37m: \x1b[35mtrue\n\x1b[37m}\n\x1b[0m')
        assert b"\x1b[34mHTTP" in result.stderr

        result = invoke("-q", "-f", url + "/missing")
        assert result.returncode == 22
        assert result.stdout == b""
        assert b"The requested URL returned error: 404" in result.stderr

        with tempfile.TemporaryDirectory() as folder:
            path = str(Path(folder) / "body.json")
            result = invoke("-q", "--pretty", "-o", path, url)
            assert result.returncode == 0
            assert result.stdout == b""
            assert Path(path).read_bytes() == b'{"a":1,"ok":true}\n'

        result = invoke("--curl", "POST", "example.test", "a=b")
        assert result.returncode == 0
        assert result.stdout == (b'curl -X POST -d {"a":"b"} example.test -s -S '
                                 b'-H "Content-Type: application/json" '
                                 b'-H "Accept: application/json, */*"\n')
        assert invoke("--definitely-unknown").returncode == 2
        assert b"Usage:" in invoke("--help").stdout
        print("CLI smoke tests passed")
    finally:
        server.shutdown()
        server.server_close()


if __name__ == "__main__":
    main()
EOF
