package main

import (
    "bytes"
    "fmt"
    "io"
    "time"
)

func traceDump(data []byte, ascii bool) string {
    var out bytes.Buffer
    width:=16
    if ascii {width=64}
    for at:=0;at<len(data); {
        fmt.Fprintf(&out,"%04x: ",at)
        if !ascii {
            for j:=0;j<width;j++ {
                if at+j<len(data){fmt.Fprintf(&out,"%02x ",data[at+j])}else{out.WriteString("   ")}
            }
        }
        start:=at
        for at<len(data)&&at-start<width {
            c:=data[at]
            if ascii && c=='\r' && at+1<len(data)&&data[at+1]=='\n'{at+=2;break}
            if c>=32 && c<127 {out.WriteByte(c)}else{out.WriteByte('.')}
            at++
        }
        out.WriteByte('\n')
    }
    return out.String()
}

func (t *transfer) writeTrace(kind int, data []byte){
    if t.trace==nil{return}
    stamp:=""
    if t.conf.traceTime{stamp=time.Now().Format("15:04:05.000000 ")}
    var text string
    if kind==0{text=stamp+"== Info: "+string(data)}else{
        labels:=map[int]string{1:"<= Recv header",2:"=> Send header",3:"<= Recv data",4:"=> Send data",5:"<= Recv SSL data",6:"=> Send SSL data"}
        if label,ok:=labels[kind];ok{text=fmt.Sprintf("%s%s, %d bytes (0x%x)\n",stamp,label,len(data),len(data))+traceDump(data,t.conf.traceASCII)}
    }
    if t.conf.traceFile=="%"{writeLines(t.trace,text,t.conf.front.PrettyErr&&!t.rawStderr)}else{io.WriteString(t.trace,text)}
}
